<!DOCTYPE html>
<html lang="ko">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Qwen3.6-27B — Self-Portrait</title>
<style>
  :root {
    --bg: #06060e;
    --text: #e8e8f0;
    --accent: #6ee7b7;
    --accent2: #818cf8;
    --accent3: #f0abfc;
    --dim: #4a4a6a;
    --font: 'Segoe UI', system-ui, -apple-system, sans-serif;
  }
  *, *::before, *::after { margin:0; padding:0; box-sizing:border-box; }
  html { font-size: 16px; scroll-behavior: smooth; }
  body {
    background: var(--bg);
    color: var(--text);
    font-family: var(--font);
    overflow-x: hidden;
    min-height: 100vh;
    line-height: 1.6;
  }
  @media (prefers-reduced-motion: reduce) {
    *, *::before, *::after {
      animation-duration: 0.01ms !important;
      animation-iteration-count: 1 !important;
      transition-duration: 0.01ms !important;
      scroll-behavior: auto !important;
    }
    canvas#bgCanvas { display: none; }
    .static-bg { display: block; }
  }
  .static-bg {
    display: none;
    position: fixed; inset: 0; z-index: 0;
    background:
      radial-gradient(ellipse at 30% 40%, rgba(110,231,183,0.08) 0%, transparent 60%),
      radial-gradient(ellipse at 70% 60%, rgba(129,140,248,0.08) 0%, transparent 60%),
      var(--bg);
  }

  /* Skip link */
  .skip-link {
    position: absolute; top: -100px; left: 1rem;
    background: var(--accent); color: var(--bg);
    padding: 0.5rem 1rem; border-radius: 0 0 8px 8px;
    z-index: 1000; font-weight: 600;
    transition: top 0.2s;
  }
  .skip-link:focus { top: 0; }

  /* Canvas */
  canvas#bgCanvas {
    position: fixed; inset: 0; z-index: 0;
    width: 100%; height: 100%;
  }

  /* Main content */
  main {
    position: relative; z-index: 1;
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem 1.5rem 4rem;
  }

  /* Header */
  header {
    text-align: center;
    padding: 4rem 0 2rem;
  }
  .model-name {
    font-size: clamp(2rem, 6vw, 3.5rem);
    font-weight: 800;
    letter-spacing: -0.02em;
    background: linear-gradient(135deg, var(--accent), var(--accent2), var(--accent3));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    margin-bottom: 0.5rem;
    line-height: 1.2;
  }
  .subtitle {
    font-size: clamp(0.9rem, 2.5vw, 1.15rem);
    color: var(--dim);
    font-weight: 400;
    letter-spacing: 0.05em;
  }

  /* Sections */
  section {
    margin: 3rem 0;
    padding: 2rem;
    border-radius: 16px;
    background: rgba(255,255,255,0.03);
    border: 1px solid rgba(255,255,255,0.06);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    transition: border-color 0.3s, box-shadow 0.3s;
  }
  section:hover, section:focus-within {
    border-color: rgba(110,231,183,0.2);
    box-shadow: 0 0 40px rgba(110,231,183,0.05);
  }
  section h2 {
    font-size: 1.3rem;
    font-weight: 700;
    margin-bottom: 1rem;
    display: flex;
    align-items: center;
    gap: 0.5rem;
  }
  section h2 .icon {
    width: 28px; height: 28px;
    border-radius: 8px;
    display: flex; align-items: center; justify-content: center;
    font-size: 0.9rem;
    flex-shrink: 0;
  }
  .icon-green { background: rgba(110,231,183,0.15); color: var(--accent); }
  .icon-blue { background: rgba(129,140,248,0.15); color: var(--accent2); }
  .icon-purple { background: rgba(240,171,252,0.15); color: var(--accent3); }

  /* Typing area */
  .typing-area {
    display: flex;
    flex-direction: column;
    gap: 1rem;
  }
  .typing-input {
    width: 100%;
    padding: 0.85rem 1rem;
    border-radius: 10px;
    border: 1px solid rgba(255,255,255,0.1);
    background: rgba(255,255,255,0.04);
    color: var(--text);
    font-size: 1rem;
    font-family: var(--font);
    outline: none;
    transition: border-color 0.3s, box-shadow 0.3s;
  }
  .typing-input:focus {
    border-color: var(--accent);
    box-shadow: 0 0 0 3px rgba(110,231,183,0.15);
  }
  .typing-input::placeholder { color: var(--dim); }
  .typing-output {
    min-height: 3rem;
    padding: 1rem;
    border-radius: 10px;
    background: rgba(110,231,183,0.03);
    border: 1px solid rgba(110,231,183,0.08);
    font-size: 1.05rem;
    line-height: 1.8;
    color: var(--accent);
    font-weight: 500;
  }
  .typing-output .cursor {
    display: inline-block;
    width: 2px; height: 1.1em;
    background: var(--accent);
    vertical-align: text-bottom;
    animation: blink 1s step-end infinite;
  }
  @keyframes blink { 50% { opacity: 0; } }

  /* Constellation */
  .constellation-wrap {
    position: relative;
    width: 100%;
    aspect-ratio: 16/9;
    max-height: 350px;
    border-radius: 12px;
    overflow: hidden;
    background: rgba(0,0,0,0.3);
  }
  canvas#constellationCanvas {
    width: 100%; height: 100%;
    display: block;
  }
  .constellation-hint {
    position: absolute;
    bottom: 0.75rem; left: 50%;
    transform: translateX(-50%);
    font-size: 0.8rem;
    color: var(--dim);
    pointer-events: none;
    white-space: nowrap;
  }

  /* Layers */
  .layers-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
    gap: 0.75rem;
  }
  .layer-card {
    padding: 1rem;
    border-radius: 10px;
    background: rgba(255,255,255,0.03);
    border: 1px solid rgba(255,255,255,0.06);
    text-align: center;
    cursor: pointer;
    transition: all 0.3s;
    user-select: none;
    outline: none;
  }
  .layer-card:hover, .layer-card:focus-visible {
    background: rgba(110,231,183,0.06);
    border-color: rgba(110,231,183,0.2);
    transform: translateY(-2px);
  }
  .layer-card .layer-num {
    font-size: 1.5rem;
    font-weight: 800;
    background: linear-gradient(135deg, var(--accent), var(--accent2));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }
  .layer-card .layer-label {
    font-size: 0.75rem;
    color: var(--dim);
    margin-top: 0.25rem;
  }
  .layer-card .layer-desc {
    font-size: 0.8rem;
    color: var(--text);
    margin-top: 0.5rem;
    opacity: 0;
    max-height: 0;
    overflow: hidden;
    transition: all 0.3s;
  }
  .layer-card.active .layer-desc {
    opacity: 1;
    max-height: 60px;
  }

  /* Parameters */
  .param-row {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin: 0.75rem 0;
    flex-wrap: wrap;
  }
  .param-label {
    min-width: 100px;
    font-size: 0.9rem;
    color: var(--dim);
    font-weight: 500;
  }
  .param-bar {
    flex: 1;
    min-width: 150px;
    height: 6px;
    border-radius: 3px;
    background: rgba(255,255,255,0.06);
    overflow: hidden;
  }
  .param-fill {
    height: 100%;
    border-radius: 3px;
    transition: width 1s ease;
  }
  .param-value {
    min-width: 50px;
    text-align: right;
    font-size: 0.85rem;
    font-weight: 600;
    font-variant-numeric: tabular-nums;
  }

  /* Footer */
  footer {
    text-align: center;
    padding: 3rem 0 2rem;
    color: var(--dim);
    font-size: 0.85rem;
  }
  footer a {
    color: var(--accent);
    text-decoration: none;
  }

  /* Accessibility panel */
  .a11y-toggle {
    position: fixed;
    bottom: 1rem; right: 1rem;
    z-index: 100;
    width: 44px; height: 44px;
    border-radius: 50%;
    border: 1px solid rgba(255,255,255,0.15);
    background: rgba(20,20,35,0.9);
    color: var(--text);
    font-size: 1.2rem;
    cursor: pointer;
    display: flex; align-items: center; justify-content: center;
    backdrop-filter: blur(10px);
    transition: all 0.3s;
  }
  .a11y-toggle:hover, .a11y-toggle:focus-visible {
    background: rgba(110,231,183,0.15);
    border-color: var(--accent);
  }
  .a11y-panel {
    position: fixed;
    bottom: 4rem; right: 1rem;
    z-index: 100;
    width: 260px;
    padding: 1.25rem;
    border-radius: 14px;
    background: rgba(15,15,30,0.95);
    border: 1px solid rgba(255,255,255,0.1);
    backdrop-filter: blur(20px);
    display: none;
    box-shadow: 0 20px 60px rgba(0,0,0,0.5);
  }
  .a11y-panel.open { display: block; }
  .a11y-panel h3 {
    font-size: 0.95rem;
    margin-bottom: 1rem;
    color: var(--accent);
  }
  .a11y-option {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin: 0.6rem 0;
    font-size: 0.85rem;
  }
  .a11y-option label { color: var(--text); cursor: pointer; }
  .toggle-switch {
    position: relative;
    width: 40px; height: 22px;
    background: rgba(255,255,255,0.1);
    border-radius: 11px;
    cursor: pointer;
    transition: background 0.3s;
    border: none;
    outline: none;
  }
  .toggle-switch::after {
    content: '';
    position: absolute;
    top: 3px; left: 3px;
    width: 16px; height: 16px;
    border-radius: 50%;
    background: var(--text);
    transition: transform 0.3s;
  }
  .toggle-switch.on {
    background: var(--accent);
  }
  .toggle-switch.on::after {
    transform: translateX(18px);
  }
  .font-size-control {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-top: 0.75rem;
  }
  .font-size-control button {
    width: 32px; height: 32px;
    border-radius: 8px;
    border: 1px solid rgba(255,255,255,0.15);
    background: rgba(255,255,255,0.05);
    color: var(--text);
    font-size: 1rem;
    cursor: pointer;
    display: flex; align-items: center; justify-content: center;
    transition: all 0.2s;
  }
  .font-size-control button:hover, .font-size-control button:focus-visible {
    background: rgba(110,231,183,0.15);
    border-color: var(--accent);
  }
  .font-size-control span {
    font-size: 0.85rem;
    color: var(--dim);
    min-width: 40px;
    text-align: center;
  }

  /* High contrast mode */
  body.high-contrast {
    --bg: #000;
    --text: #fff;
    --dim: #ccc;
  }
  body.high-contrast section {
    background: rgba(255,255,255,0.06);
    border-color: rgba(255,255,255,0.2);
  }

  /* Focus visible */
  :focus-visible {
    outline: 2px solid var(--accent);
    outline-offset: 2px;
  }

  /* Responsive */
  @media (max-width: 600px) {
    main { padding: 1rem 1rem 3rem; }
    header { padding: 2.5rem 0 1.5rem; }
    section { padding: 1.25rem; margin: 2rem 0; }
    .layers-grid { grid-template-columns: repeat(3, 1fr); }
    .constellation-wrap { aspect-ratio: 4/3; }
  }

  /* Pulse animation for model name */
  @keyframes pulse-glow {
    0%, 100% { filter: brightness(1); }
    50% { filter: brightness(1.2); }
  }
  .model-name { animation: pulse-glow 4s ease-in-out infinite; }
  @media (prefers-reduced-motion: reduce) {
    .model-name { animation: none; }
  }
</style>
</head>
